insert into public.diagnostico_items
  (id, area, tipo, peso, elo, elo_base, enunciado, opciones, fen, correcta, solucion, alternas, explica, lichess, rating)
values
  ('mat_calidad_definicion', 'material', 'opcion', 3, 1550, 1200, 'En ajedrez, ¿a qué se le llama exactamente «la calidad»?', '["A la diferencia entre torre y pieza menor","Al valor de todas las piezas que quedan","A lo bien que juega alguien, sin el material","Al número de peones que le queda a cada uno"]'::jsonb, null, 0, null, null, '«La calidad» es concretamente la diferencia de valor entre una torre (5) y una pieza menor (3). Ganar la calidad es cambiar tu pieza menor por una torre rival; perderla es lo contrario.', null, null),
  ('mat_peon_de_mas', 'material', 'opcion', 1, 1000, 950, 'En un final con el resto del material igualado, ¿qué suele significar tener un peón de más?', '["Una ventaja real, pero hay que saber jugarla","Nada: un peón suelto no cambia el resultado","La derrota segura del que tiene menos peones","Que la partida se declara tablas de inmediato"]'::jsonb, null, 0, null, null, 'Un peón de más es una ventaja genuina, sobre todo en finales, pero no gana sola: convertirla en punto entero exige técnica. Por eso los finales se estudian.', null, null),
  ('mat_ganando_cambiar', 'material', 'opcion', 1, 940, 1200, 'Si vas ganando en material, ¿qué principio práctico suele convenir?', '["Cambiar piezas para simplificar hacia el final","Evitar todo cambio de piezas a cualquier precio","Cambiar cuanto antes todos los peones que haya","Entregar la ventaja para complicar la posición"]'::jsonb, null, 0, null, null, 'Con material de más conviene cambiar piezas y conservar peones: menos piezas rivales significan menos contrajuego, y los peones son los que coronan. La regla corta es «cambia piezas, no peones».', null, null),
  ('mat_perdiendo_complicar', 'material', 'opcion', 1, 1060, 1200, 'Si vas perdiendo en material, ¿qué principio práctico suele convenir?', '["Evitar los cambios y buscar complicaciones","Cambiar cuanto antes todas las piezas que haya","Abandonar apenas se pierde el primer peón","Ofrecer tablas en todas y cada una de las jugadas"]'::jsonb, null, 0, null, null, 'Con material de menos, simplificar es entregarse: cuantas más piezas queden, más posibilidades hay de que el rival se equivoque. Es el reverso exacto del principio anterior.', null, null),
  ('mat_caballo_cerrada', 'material', 'opcion', 2, 1220, 1200, '¿En qué tipo de posición suelen rendir mejor los caballos que los alfiles?', '["En posiciones cerradas, con los peones trabados","En posiciones abiertas, sin ningún peón en medio","En ninguna: el caballo nunca supera al alfil","Solo en el momento justo de enrocar"]'::jsonb, null, 0, null, null, 'El caballo salta por encima de los peones, así que una posición trabada no lo estorba. El alfil necesita diagonales despejadas: encerrado detrás de sus propios peones vale mucho menos de lo que dice la tabla.', null, null),
  ('mat_tres_menores', 'material', 'opcion', 2, 1290, 1450, 'En valor aproximado, ¿a qué suelen equivaler tres piezas menores?', '["A una dama, más o menos: 3+3+3 son 9","A bastante menos que media dama","A todavía menos que una sola torre","Al doble exacto de lo que vale la dama"]'::jsonb, null, 0, null, null, 'Tres menores suman unos 9 puntos, el valor de una dama. En la práctica suelen ser mejores que la dama si tienen casillas donde apoyarse: tres piezas coordinadas atacan más cosas a la vez que una sola.', null, null),
  ('mat_torre_y_peon', 'material', 'opcion', 1, 1090, 1450, 'En puntos, ¿a qué equivale aproximadamente una torre junto con un peón?', '["A dos piezas menores: 5+1 contra 3+3","A una dama entera, con sus 9 puntos","A un solo caballo, ni más ni menos","A nada: el peón no suma al lado de una torre"]'::jsonb, null, 0, null, null, 'Torre más peón son 6 puntos, y dos piezas menores también. Es un desequilibrio clásico y ninguno de los dos lados está objetivamente mejor: depende de si la posición es abierta (mejor la torre) o cerrada (mejores las menores).', null, null),
  ('mat_un_peon_decide', 'material', 'opcion', 2, 1380, 1450, 'Entre jugadores de nivel parecido, ¿qué ventaja de material suele bastar para ganar con buena técnica?', '["Un solo peón, bien jugado, ya puede decidir","Hace falta ganar una torre entera, como mínimo","El material nunca decide: solo el ataque directo","Hace falta capturar la dama del rival"]'::jsonb, null, 0, null, null, 'Entre jugadores fuertes, un peón de ventaja bien manejado suele alcanzar. Por eso en el ajedrez de alto nivel se pelea cada peón como si fuera una pieza.', null, null),
  ('mat_pieza_atrapada', 'material', 'opcion', 2, 1140, 950, '¿Qué significa que una pieza esté «atrapada»?', '["Que no tiene casilla segura y va a caer","Que está clavada contra su propio rey","Que acaba de coronar en la última fila","Que se quedó encerrada por el enroque"]'::jsonb, null, 0, null, null, 'Una pieza atrapada todavía se puede mover, pero todas sus casillas de salida están controladas: se pierde igual. Cazar una pieza atrapada es una de las formas más limpias de ganar material.', null, null),
  ('mat_pieza_colgada', 'material', 'opcion', 1, 820, 950, '¿A qué se le llama que una pieza esté «colgada»?', '["A que está sin defensa y se puede tomar","A que está a punto de coronar en dama","A que se quedó sola en la última fila","A que acaba de enrocar junto a su rey"]'::jsonb, null, 0, null, null, 'Una pieza colgada está desprotegida: si el rival la toma, no hay recaptura y el material se pierde gratis. Revisar las piezas colgadas —las propias y las del rival— antes de cada jugada evita la mitad de las derrotas.', null, null),
  ('mat_contar_material', 'material', 'opcion', 1, 800, 700, 'Para saber rápido quién va ganando en material durante una partida, ¿qué conviene hacer?', '["Sumar los valores de cada bando y comparar","Contar las piezas, sin mirar de cuáles son","Dejar los peones fuera de la cuenta","Mirar solo el tiempo que queda en el reloj"]'::jsonb, null, 0, null, null, 'Sumar los valores aproximados de cada bando —peón 1, menor 3, torre 5, dama 9— y comparar los dos totales da una idea rápida y confiable de quién está mejor.', null, null),
  ('mat_caballo_vs_peon', 'material', 'opcion', 1, 570, 700, 'En la inmensa mayoría de posiciones, ¿qué vale más: un caballo o un peón?', '["El caballo, con claridad: 3 contra 1","El peón, siempre y en toda posición","Los dos valen exactamente lo mismo","Depende solo del color de las piezas"]'::jsonb, null, 0, null, null, 'El caballo vale unos 3 puntos y el peón 1. Por eso entregar un caballo para ganar «solo» un peón casi nunca compensa, salvo que a cambio se consiga algo grande.', null, null),
  ('mat_alcance_mayores', 'material', 'opcion', 1, 960, 1200, '¿Por qué torres y dama se consideran especialmente peligrosas al atacar al rey rival?', '["Por su alcance: atacan desde lejos","Porque solo ellas pueden dar jaque mate","Porque valen menos que las piezas menores","Porque no se las puede capturar nunca"]'::jsonb, null, 0, null, null, 'Las piezas mayores atacan filas y columnas enteras —y la dama además las diagonales—, así que amenazan al rey desde el otro lado del tablero, sin tener que acercarse casilla a casilla como el caballo.', null, null),
  ('ap_principios', 'apertura', 'opcion', 1, 610, 700, 'En la apertura, ¿cuál de estos es un principio básico recomendado?', '["Controlar el centro y desarrollar las menores","Sacar la dama lo antes posible al tablero","Mover primero los peones de las dos torres","Enrocar en la primera jugada, sin excepción"]'::jsonb, null, 0, null, null, 'Los tres principios clásicos son: controlar el centro, desarrollar rápido las piezas menores y poner el rey a salvo con el enroque. Casi todo lo demás de la apertura sale de ahí.', null, null),
  ('ap_gambito_dama', 'apertura', 'opcion', 1, 1090, 700, '1.d4 d5 2.c4 es el…', '["Gambito de Dama","Gambito de Rey","Ataque Colle","Sistema Londres"]'::jsonb, null, 0, null, null, 'Las blancas ofrecen el peón de c4 para desviar el peón de d5 y quedarse con el centro. Se llama gambito aunque el peón casi siempre se recupera.', null, null),
  ('ap_francesa', 'apertura', 'opcion', 2, 1140, 700, '1.e4 e6 corresponde a la Defensa…', '["Francesa","Siciliana","Escandinava","Alekhine"]'::jsonb, null, 0, null, null, 'Prepara …d5 con una estructura sólida y contrajuego típico en el flanco de dama. Su punto flojo conocido es el alfil de casillas claras, que queda encerrado detrás de los peones.', null, null),
  ('ap_italiana', 'apertura', 'opcion', 1, 960, 950, '1.e4 e5 2.Cf3 Cc6 3.Ac4 corresponde a la apertura…', '["Italiana (Giuoco Piano)","Española (la Ruy López)","Escocesa abierta","Siciliana cerrada"]'::jsonb, null, 0, null, null, 'Cuando el alfil va a c4 en vez de b5, es la Italiana: el alfil apunta directo a f7, que es la casilla más débil del bando negro al empezar la partida.', null, null),
  ('ap_escocesa', 'apertura', 'opcion', 3, 1410, 950, '1.e4 e5 2.Cf3 Cc6 3.d4 corresponde a la apertura…', '["Escocesa","Italiana","Española","Francesa"]'::jsonb, null, 0, null, null, 'Abrir el centro con d4 en la tercera jugada es la seña de la Escocesa: cambia el centro enseguida y lleva a posiciones abiertas, con menos teoría que la Española.', null, null),
  ('ap_caro_kann', 'apertura', 'opcion', 3, 1410, 950, '1.e4 c6 corresponde a la Defensa…', '["Caro-Kann","Siciliana","Francesa","Pirc"]'::jsonb, null, 0, null, null, 'Prepara …d5 igual que la Francesa, pero sin encerrar el alfil de casillas claras: por eso tiene fama de sólida. Ese alfil suele salir a f5 antes de cerrar la cadena de peones.', null, null),
  ('ap_pirc', 'apertura', 'opcion', 3, 1630, 1200, '1.e4 d6, seguido normalmente de …Cf6, …g6 y …Ag7, corresponde a la Defensa…', '["Pirc","Caro-Kann","Escandinava","Nimzoindia"]'::jsonb, null, 0, null, null, 'Es una defensa hipermoderna: deja que las blancas ocupen el centro con peones y lo contraataca después con las piezas, apoyándose en el alfil fianchettado en g7.', null, null),
  ('ap_escandinava', 'apertura', 'opcion', 2, 1340, 950, '1.e4 d5 corresponde a la Defensa…', '["Escandinava","Francesa","Caro-Kann","Alekhine"]'::jsonb, null, 0, null, null, 'Las negras cambian el peón central de inmediato y suelen recapturar con la dama. El precio es que esa dama queda expuesta a Cc3, que gana un tiempo.', null, null),
  ('ap_alekhine', 'apertura', 'opcion', 3, 1670, 1200, '1.e4 Cf6 corresponde a la Defensa…', '["Alekhine","Escandinava","Pirc","India de Rey"]'::jsonb, null, 0, null, null, 'El caballo se ofrece de blanco a propósito: provoca que los peones blancos avancen y después ataca esa cadena adelantada. Es la defensa hipermoderna más provocadora.', null, null),
  ('ap_reti', 'apertura', 'opcion', 3, 1400, 1450, '1.Cf3, sin definir todavía el destino de los peones centrales, suele llamarse Apertura…', '["Réti","Inglesa","Española","Escocesa"]'::jsonb, null, 0, null, null, 'Deja para más adelante qué van a hacer los peones centrales y a menudo fianchetta un alfil. Es de las que más transponen: puede terminar en una Inglesa, en un Gambito de Dama o en un sistema propio.', null, null),
  ('ap_inglesa', 'apertura', 'opcion', 3, 1500, 950, '1.c4 corresponde a la Apertura…', '["Inglesa","Holandesa","India de Rey","Nimzoindia"]'::jsonb, null, 0, null, null, 'Ataca el centro desde el flanco de dama sin ocuparlo con un peón central. Es la tercera primera jugada más jugada, detrás de 1.e4 y 1.d4.', null, null),
  ('ap_india_rey', 'apertura', 'opcion', 2, 1370, 1200, '1.d4 Cf6 2.c4 g6, con la idea de seguir …Ag7, corresponde a la Defensa…', '["India de Rey","Nimzoindia","Holandesa","Escandinava"]'::jsonb, null, 0, null, null, 'Deja que las blancas ocupen el centro y lo contraataca después con …e5 o …c5, con el alfil de g7 apuntando a la diagonal larga. Es una defensa de contraataque, no de igualar rápido.', null, null),
  ('ap_nimzoindia', 'apertura', 'opcion', 3, 1630, 1450, '1.d4 Cf6 2.c4 e6 3.Cc3 Ab4 corresponde a la Defensa…', '["Nimzoindia","India de Rey","Holandesa","Gambito de Dama"]'::jsonb, null, 0, null, null, 'Clavar el caballo de c3 con el alfil en b4, en vez de jugar …d5, es su seña de identidad. La idea es cambiar ese alfil por el caballo y dejarle a las blancas los peones doblados.', null, null),
  ('ap_holandesa', 'apertura', 'opcion', 3, 1510, 1200, '1.d4 f5 corresponde a la Defensa…', '["Holandesa","India de Rey","Nimzoindia","Benoni"]'::jsonb, null, 0, null, null, 'Las negras pelean por e4 desde el flanco de rey. El costo está a la vista: el peón de f ya no cubre al rey, así que es una defensa de doble filo.', null, null),
  ('ap_sistema_londres', 'apertura', 'opcion', 2, 1230, 1200, 'El «Sistema Londres» se caracteriza porque las blancas…', '["Arman siempre la misma estructura, juegue lo que juegue el rival","Solo lo pueden jugar contra la Defensa Siciliana, y no contra otra","Tienen que memorizar decenas de variantes forzadas de memoria","Entregan un peón en la primera jugada para abrir líneas"]'::jsonb, null, 0, null, null, 'Es un «sistema» y no una apertura teórica: el peón a d4, el alfil a f4 y el resto casi siempre en las mismas casillas. Por eso es tan popular entre quienes no quieren estudiar teoría, aunque a cambio pide menos ventaja.', null, null),
  ('ap_fianchetto', 'apertura', 'opcion', 2, 1220, 950, '¿Qué es un «fianchetto»?', '["Poner el alfil en la diagonal larga, tras su peón","Un tipo especial de enroque que se hace con el alfil","Entregar un peón a cambio de tomar la iniciativa","Otro nombre que se le da a la clavada de una pieza"]'::jsonb, null, 0, null, null, 'Se avanza el peón de b o de g una casilla y el alfil se pone detrás, en b2/g2 o en b7/g7, mirando toda la diagonal larga. Es la jugada típica de las defensas hipermodernas.', null, null),
  ('ap_gambito_rey', 'apertura', 'opcion', 2, 1320, 950, '1.e4 e5 2.f4 es el…', '["Gambito de Rey","Gambito de Dama","Ataque Colle","Sistema Londres"]'::jsonb, null, 0, null, null, 'Las blancas ofrecen el peón de f para abrir esa columna y atacar rápido. Fue la apertura de moda del siglo XIX y hoy casi no se ve en alto nivel: debilita demasiado al propio rey.', null, null),
  ('ap_enrocar_antes', 'apertura', 'opcion', 1, 980, 950, '¿Por qué suele convenir enrocar antes de abrir demasiado el centro?', '["Para sacar al rey antes de que se abran líneas","Porque el enroque suma puntos de material","Porque el reglamento lo exige antes de la jugada 10","Porque así el rival no puede desarrollar sus piezas"]'::jsonb, null, 0, null, null, 'Un centro abierto son columnas y diagonales por las que llegan las piezas rivales, y el rey en el centro está justo en medio de todas. Enrocar primero lo pone fuera de esa zona.', null, null),
  ('ap_dos_veces_misma', 'apertura', 'opcion', 1, 880, 950, 'En la apertura, ¿por qué se recomienda no mover dos veces la misma pieza sin una buena razón?', '["Porque cada jugada repetida es un tiempo regalado","Porque las reglas del ajedrez no lo permiten","Porque esa pieza queda inmóvil el resto de la partida","Porque al hacerlo se pierde el derecho al enroque"]'::jsonb, null, 0, null, null, 'Cada jugada de apertura que no saca una pieza nueva es un «tiempo» que el rival usa para adelantarse en desarrollo. Con dos o tres tiempos de ventaja ya se puede empezar un ataque.', null, null),
  ('ap_ideas_vs_memoria', 'apertura', 'opcion', 2, 1120, 1200, 'Para un jugador principiante o intermedio, ¿qué suele ser más útil que memorizar largas variantes de apertura?', '["Entender las ideas y los planes de su apertura","Memorizar veinte jugadas exactas sin entenderlas","Cambiar de apertura en cada partida que juega","No estudiar aperturas en absoluto, nunca"]'::jsonb, null, 0, null, null, 'Entender qué casillas hay que controlar y qué plan sigue la apertura sirve también cuando el rival se sale de la teoría — que en estos niveles pasa en la jugada 4. La memoria pura se cae ahí mismo.', null, null),
  ('ap_transposicion', 'apertura', 'opcion', 3, 1480, 1450, '¿Qué es una «transposición» de aperturas?', '["Llegar a la misma posición por otro orden de jugadas","Cambiarse de bando cuando la partida va por la mitad","Repetir tres veces seguidas la misma jugada exacta","Un tipo de gambito que casi nadie juega hoy"]'::jsonb, null, 0, null, null, 'Dos partidas que empezaron distinto pueden terminar en la misma posición. Por eso el orden de jugadas importa: se usa para entrar a una apertura evitando la variante que el rival prefiere.', null, null),
  ('tac_horquilla_nombre', 'tactica', 'opcion', 1, 660, 700, '¿Cómo se llama la táctica en la que una pieza ataca a dos piezas rivales a la vez?', '["Tenedor (o tenedor)","Clavada de una pieza","Rayos X sobre la fila","Enroque por el centro"]'::jsonb, null, 0, null, null, 'Es un ataque doble hecho por una sola pieza. El caballo es el rey del tenedor porque ataca casillas que ninguna otra pieza defiende de la misma forma.', null, null),
  ('tac_clavada_nombre', 'tactica', 'opcion', 1, 720, 700, '¿Cómo se llama la táctica en la que una pieza no puede moverse porque detrás de ella, en la misma línea, está su rey u otra pieza más valiosa?', '["Clavada","Tenedor","Descubierta","Ahogado"]'::jsonb, null, 0, null, null, 'La pieza clavada queda inmovilizada —o castigada si se mueve— porque al apartarse deja expuesto lo que tenía detrás. Solo clavan las piezas de línea: alfil, torre y dama.', null, null),
  ('tac_descubierto_que_es', 'tactica', 'opcion', 1, 940, 950, 'En un «ataque descubierto», ¿qué ocurre?', '["Una pieza se aparta y descubre el ataque de otra","Dos piezas propias se mueven en la misma jugada","El rey queda expuesto y pierde el enroque","Aparece un peón pasado que estaba escondido"]'::jsonb, null, 0, null, null, 'La pieza que se mueve abre la línea de otra que estaba detrás, y esa segunda ataca sin haberse movido. Es doblemente peligroso porque la pieza que se aparta puede ir a hacer daño por su cuenta.', null, null),
  ('tac_horquilla_familiar', 'tactica', 'opcion_tablero', 1, 880, 950, 'Juegan las blancas. ¿Cuál de estas jugadas del caballo gana material con un tenedor?', '["Cc7+","Cd6+","Ca7","Cc3"]'::jsonb, 'r3k3/8/8/1N6/8/8/8/4K3 w - - 0 1', 0, null, null, 'Cc7+ da jaque al rey de e8 y ataca la torre de a8 al mismo tiempo: la clásica «tenedor familiar». Las negras tienen que atender el jaque y las blancas se llevan la torre. Cd6+ también da jaque, pero no amenaza nada; Ca7 y Cc3 ni siquiera dan jaque.', null, null),
  ('tac_pasillo_tablero', 'tactica', 'opcion_tablero', 1, 770, 950, 'Juegan las blancas. ¿Cuál de estas jugadas de la torre da jaque mate?', '["Te8#","Te7","Td1","Rg2"]'::jsonb, '6k1/5ppp/8/8/8/8/8/4R1K1 w - - 0 1', 0, null, null, 'Te8 es mate del pasillo: el rey negro está encerrado por sus propios peones de f7, g7 y h7, y nadie puede capturar la torre ni meterse en la fila 8. Es la razón por la que conviene hacerle un respiradero al rey.', null, null),
  ('tac_ataque_doble', 'tactica', 'opcion', 1, 910, 950, '¿Cómo se le llama, en general, a cualquier jugada que amenaza dos objetivos rivales al mismo tiempo?', '["Ataque doble","Enroque doble","Jaque perpetuo","Zugzwang mutuo"]'::jsonb, null, 0, null, null, 'El tenedor es el caso más conocido, pero el término general abarca cualquier jugada que cree dos amenazas a la vez, sea con una sola pieza o mediante una descubierta. El rival solo puede parar una.', null, null),
  ('tac_clavada_absoluta', 'tactica', 'opcion', 2, 1100, 950, '¿Cómo se llama la clavada en la que la pieza clavada NO se puede mover de ninguna manera, porque detrás está el propio rey?', '["Clavada absoluta","Clavada relativa","Tenedor de rey","Rayos X directo"]'::jsonb, null, 0, null, null, 'Mover esa pieza dejaría al rey en jaque, y eso es ilegal: la pieza queda completamente quieta. Una pieza en clavada absoluta tampoco defiende de verdad, aunque parezca que sí.', null, null),
  ('tac_clavada_relativa', 'tactica', 'opcion', 2, 1250, 1200, '¿Cómo se llama la clavada en la que sí es legal mover la pieza clavada, pero conviene no hacerlo porque detrás hay algo más valioso que no es el rey?', '["Clavada relativa","Clavada absoluta","Ataque descubierto","Desviación forzada"]'::jsonb, null, 0, null, null, 'Acá mover es legal, solo que sale caro: se expone la pieza de atrás. A veces vale la pena romper la clavada igual, si lo que se gana supera lo que se entrega.', null, null),
  ('tac_jaque_descubierto', 'tactica', 'opcion', 1, 1040, 950, 'Cuando un ataque descubierto además da jaque al rey rival, ¿cómo se llama esa jugada?', '["Jaque descubierto","Jaque intermedio","Jaque perpetuo","Jaque de molino"]'::jsonb, null, 0, null, null, 'Es el caso particular en que la pieza de atrás apunta al rey. Lo temible es que la pieza que se aparta puede irse a capturar donde quiera: el rival está obligado a atender el jaque.', null, null),
  ('tac_zwischenzug', 'tactica', 'opcion', 3, 1440, 1450, '¿Qué es una «jugada intermedia» (zwischenzug)?', '["Una jugada fuerte metida antes de la esperada","La primera jugada de cualquier apertura conocida","Una jugada que no cambia nada de la posición","Una jugada ilegal que hay que volver atrás"]'::jsonb, null, 0, null, null, 'En vez de recapturar en el acto, como el rival da por hecho, se intercala otra jugada más fuerte —normalmente un jaque o una amenaza mayor— y recién después se completa el cambio. Es de lo que más se pasa por alto al calcular.', null, null),
  ('tac_combinacion', 'tactica', 'opcion', 2, 1290, 950, 'En ajedrez, ¿qué es una «combinación»?', '["Una serie forzada de jugadas con un fin concreto","Cualquier jugada que desarrolla una pieza nueva","Un tipo de apertura que casi nadie juega hoy","Exactamente lo mismo que se llama estrategia"]'::jsonb, null, 0, null, null, 'Lo que la define es que es forzada: el rival casi no tiene alternativas. Suele incluir un sacrificio y termina en ganancia clara de material o en mate.', null, null),
  ('tac_f7_debil', 'tactica', 'opcion', 2, 1210, 950, 'En las primeras jugadas, ¿por qué la casilla f7 (f2 para las blancas) suele ser objetivo de ataques tempranos?', '["Porque al empezar solo la defiende el rey","Porque ahí siempre aparece un peón pasado","Porque es la única casilla de enroque","Porque ningún alfil puede llegar ahí"]'::jsonb, null, 0, null, null, 'Antes de enrocar, f7 tiene un solo defensor: el propio rey. Por eso tantas combinaciones de apertura apuntan ahí, desde el mate pastor hasta el sacrificio de caballo en f7.', null, null),
  ('tac_mate_pastor', 'tactica', 'opcion', 1, 950, 700, '¿Cómo se llama el intento de mate rápido que ataca f7 combinando la dama y el alfil desde la apertura?', '["Mate pastor","Mate sofocado","Mate de escalera","Mate del pasillo"]'::jsonb, null, 0, null, null, 'Aprovecha que f7 está poco defendida al principio. Se para fácil —basta con defender f7 y desarrollar—, y quien lo intenta y falla queda con la dama fuera de juego.', null, null),
  ('tac_trampa_apertura', 'tactica', 'opcion', 1, 1060, 950, '¿Qué es una «trampa de apertura»?', '["Jugadas que castigan una respuesta natural pero mala","Una jugada ilegal disfrazada de jugada normal","Un gambito que nunca se puede aceptar sin perder material","Una regla especial que solo se aplica en torneos"]'::jsonb, null, 0, null, null, 'Aprovechan que ciertas jugadas parecen lógicas y esconden un error táctico. Sirven para ganar rápido, pero apoyarse solo en ellas no enseña a jugar: el rival que no cae deja una posición normal.', null, null),
  ('tac_sacrificio_griego', 'tactica', 'opcion', 2, 1190, 1450, '¿Cómo se conoce el clásico sacrificio de alfil en h7 (o h2), capturando el peón que cubre al rey enrocado?', '["El sacrificio griego","El mate de la coz","El gambito de rey","La regla de Tarrasch"]'::jsonb, null, 0, null, null, 'El alfil se entrega en h7 para sacar al rey de su refugio; después suele venir Cg5+ y la dama entra al ataque. No siempre funciona: hay que comprobar antes que las piezas del ataque lleguen a tiempo.', null, null),
  ('tac_atacar_clavada', 'tactica', 'opcion', 1, 900, 1200, 'Si el rival tiene una pieza clavada que no es el rey, ¿qué principio táctico conviene seguir?', '["Atacarla más veces de las que la puede defender","Ignorarla: una pieza clavada no se gana nunca","Cambiarla de inmediato, pieza por pieza","Retirar las piezas propias de esa zona"]'::jsonb, null, 0, null, null, 'La pieza clavada no puede huir sin exponer lo que tiene detrás, así que es un blanco quieto: se le suman atacantes hasta que el defensor no da abasto. Un peón que la ataque suele ser lo más eficaz.', null, null)
